import{_ as a,o as t,c as o,a4 as r}from"./chunks/framework.B6zrJok8.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"title":"Glossary"},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":null}'),i={name:"glossary.md"};function n(s,e,d,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Definitions of key terms used throughout the SFCC Campaign Automation documentation.</p><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="action" tabindex="-1">Action <a class="header-anchor" href="#action" aria-label="Permalink to &quot;Action&quot;">​</a></h3><p>An instruction indicating how to process a zone. See <a href="/concepts/action-types.html">Action Types</a>.</p><table tabindex="0"><thead><tr><th>Action</th><th>Meaning</th></tr></thead><tbody><tr><td>LAUNCH</td><td>Create new content</td></tr><tr><td>UPDATE</td><td>Modify existing content</td></tr><tr><td>REMOVE</td><td>Delete content</td></tr><tr><td>SKIP</td><td>Ignore this zone</td></tr><tr><td>NO_CHANGE</td><td>Reuse existing content</td></tr><tr><td>HOTFIX</td><td>Emergency update</td></tr></tbody></table><h3 id="asset" tabindex="-1">Asset <a class="header-anchor" href="#asset" aria-label="Permalink to &quot;Asset&quot;">​</a></h3><p>See <a href="#content-asset">Content Asset</a>.</p><h3 id="asset-id" tabindex="-1">Asset ID <a class="header-anchor" href="#asset-id" aria-label="Permalink to &quot;Asset ID&quot;">​</a></h3><p>Unique identifier for a content asset in SFCC. See <a href="/concepts/asset-id-rules.html">Asset ID Rules</a>.</p><p><strong>Single-zone:</strong> <code>{brand}-{date}-{refreshId}-{assetType}</code> — e.g., <code>loft-2026-02-03-r1-pph</code></p><p><strong>Multi-zone:</strong> <code>{brand}-{date}-{refreshId}-{assetType}-{zone}</code> — e.g., <code>loft-2026-02-03-r1-homepage-hp-hero</code></p><h3 id="asset-registry" tabindex="-1">Asset Registry <a class="header-anchor" href="#asset-registry" aria-label="Permalink to &quot;Asset Registry&quot;">​</a></h3><p>JSON file tracking current asset IDs for each zone. Enables NO_CHANGE action and asset reuse. See <a href="/config/registry.html">Asset Registry</a>.</p><h3 id="asset-type" tabindex="-1">Asset Type <a class="header-anchor" href="#asset-type" aria-label="Permalink to &quot;Asset Type&quot;">​</a></h3><p>Category of promotional content (PPH, POPUP, HOMEPAGE, etc.). Defined in <code>slots.config.js</code>. See <a href="/config/slots.html">Slots &amp; Asset Types</a>.</p><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><h3 id="brand" tabindex="-1">Brand <a class="header-anchor" href="#brand" aria-label="Permalink to &quot;Brand&quot;">​</a></h3><p>A distinct e-commerce property. Currently: <code>loft</code> (LOFT) and <code>ann</code> (Ann Taylor).</p><h3 id="brandcontext" tabindex="-1">BrandContext <a class="header-anchor" href="#brandcontext" aria-label="Permalink to &quot;BrandContext&quot;">​</a></h3><p>Dependency injection container providing access to all services for a specific brand. The composition root of the application.</p><h3 id="build-guard" tabindex="-1">Build Guard <a class="header-anchor" href="#build-guard" aria-label="Permalink to &quot;Build Guard&quot;">​</a></h3><p>Safety check that prevents <code>make build</code> from overwriting already-built or already-synced dates. Reads <code>sync-config.json</code> and <code>ocapi-payload.json</code> to determine state. Bypassed by <code>make build FORCE=1</code> (<code>--force</code>). See <a href="/cli/build.html">build</a>.</p><h3 id="business-manager" tabindex="-1">Business Manager <a class="header-anchor" href="#business-manager" aria-label="Permalink to &quot;Business Manager&quot;">​</a></h3><p>Salesforce Commerce Cloud&#39;s administrative interface for managing content, products, and site configuration.</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="campaign" tabindex="-1">Campaign <a class="header-anchor" href="#campaign" aria-label="Permalink to &quot;Campaign&quot;">​</a></h3><p>Time-bound promotional entity in SFCC that coordinates when content appears on the website. Contains slot configurations and dates.</p><h3 id="campaign-id" tabindex="-1">Campaign ID <a class="header-anchor" href="#campaign-id" aria-label="Permalink to &quot;Campaign ID&quot;">​</a></h3><p>Unique identifier for a campaign. Format: <code>{brand}-{date}-{refreshId}</code>.</p><p>Example: <code>loft-2026-02-03-r1</code></p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><p>Command Line Interface. The primary way to interact with the automation tool. See <a href="/cli/">CLI Reference</a>.</p><h3 id="compilerefresh" tabindex="-1">CompileRefresh <a class="header-anchor" href="#compilerefresh" aria-label="Permalink to &quot;CompileRefresh&quot;">​</a></h3><p>Use case that transforms Refresh DTOs into Campaign domain models.</p><h3 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h3><p>The process of combining multiple zone templates into a single preview file.</p><h3 id="content-asset" tabindex="-1">Content Asset <a class="header-anchor" href="#content-asset" aria-label="Permalink to &quot;Content Asset&quot;">​</a></h3><p>A self-contained HTML fragment stored in SFCC&#39;s Content Library. Content assets are the atomic units of promotional content that fill slots on web pages. They contain HTML markup and inline CSS but cannot include <code>&lt;html&gt;</code>, <code>&lt;head&gt;</code>, or <code>&lt;body&gt;</code> tags. See <a href="/concepts/slots-assets-zones.html">Slots, Assets, Zones</a>.</p><h3 id="content-library" tabindex="-1">Content Library <a class="header-anchor" href="#content-library" aria-label="Permalink to &quot;Content Library&quot;">​</a></h3><p>SFCC&#39;s storage for content assets. Identified by <code>SFCC_LIBRARY_ID</code>.</p><h3 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>Scope of a slot configuration: <code>global</code> (site-wide) or <code>category</code> (category-specific).</p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="data-quality-gate" tabindex="-1">Data Quality Gate <a class="header-anchor" href="#data-quality-gate" aria-label="Permalink to &quot;Data Quality Gate&quot;">​</a></h3><p>Automatic validation step in <code>make push</code> that checks for missing copy, duplicate IPIDs, unknown asset types, and other data issues before syncing to SFCC. Errors block the push; warnings prompt for confirmation. See <a href="/cli/push.html">push</a>.</p><h3 id="date-state" tabindex="-1">Date State <a class="header-anchor" href="#date-state" aria-label="Permalink to &quot;Date State&quot;">​</a></h3><p>The lifecycle state of a refresh date: NEW (fetched), READY (built), SYNCED (pushed to SFCC), DONE (email sent). Displayed in <code>make status</code> dashboard. See <a href="/reference/commands.html#date-states">Date States</a>.</p><h3 id="dev-cli" tabindex="-1">Dev CLI <a class="header-anchor" href="#dev-cli" aria-label="Permalink to &quot;Dev CLI&quot;">​</a></h3><p>The set of commands intended for the web developer: <code>demo</code>, <code>registry</code>, <code>upload</code>, <code>test</code>, <code>check</code>, <code>clean</code>, <code>docs</code>, <code>log</code>. <code>make build</code> builds then watches templates + config (save = rebuild). Run <code>make dev</code> to see the full list. See <a href="/reference/commands.html#dev-commands">Commands</a>.</p><h3 id="developer-mode" tabindex="-1">Developer Mode <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;Developer Mode&quot;">​</a></h3><p>Asset type mode where HTML is provided directly (not rendered from templates). Used for complex layouts like Homepage.</p><h3 id="dry-run" tabindex="-1">Dry Run <a class="header-anchor" href="#dry-run" aria-label="Permalink to &quot;Dry Run&quot;">​</a></h3><p>Running a command without making actual changes. Use <code>--dry-run</code> flag.</p><h3 id="dev-files" tabindex="-1">Dev Files <a class="header-anchor" href="#dev-files" aria-label="Permalink to &quot;Dev Files&quot;">​</a></h3><p>The generated output files for a refresh: HTML templates, rendered previews, asset JSON files, and the OCAPI payload. Stored in <code>dev-env/{brand}/refreshes/{date}/{refreshId}/</code>.</p><h3 id="dto" tabindex="-1">DTO <a class="header-anchor" href="#dto" aria-label="Permalink to &quot;DTO&quot;">​</a></h3><p>Data Transfer Object — a plain object for passing data between application layers without business logic. The Refresh is a DTO that carries wireframe data from the parser to the compiler.</p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="excel-parser" tabindex="-1">Excel Parser <a class="header-anchor" href="#excel-parser" aria-label="Permalink to &quot;Excel Parser&quot;">​</a></h3><p>Service that parses wireframe Excel files into Refresh DTOs. Supports multiple formats.</p><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><h3 id="generatedevfiles" tabindex="-1">GenerateDevFiles <a class="header-anchor" href="#generatedevfiles" aria-label="Permalink to &quot;GenerateDevFiles&quot;">​</a></h3><p>Use case that generates HTML/JSON assets and OCAPI payload from Campaign entities.</p><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><h3 id="handlebars" tabindex="-1">Handlebars <a class="header-anchor" href="#handlebars" aria-label="Permalink to &quot;Handlebars&quot;">​</a></h3><p>Template engine used for rendering HTML from templates. See <a href="/guides/templates.html">Template Authoring</a>.</p><h3 id="hotfix" tabindex="-1">Hotfix <a class="header-anchor" href="#hotfix" aria-label="Permalink to &quot;Hotfix&quot;">​</a></h3><p>Emergency update workflow for quick content fixes. Uses the HOTFIX <a href="/concepts/action-types.html#hotfix">action type</a> to force-regenerate and sync even in DEVELOPER mode.</p><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="launch" tabindex="-1">LAUNCH <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;LAUNCH&quot;">​</a></h3><p>Action indicating new content creation. Generates new asset ID and registers in registry.</p><h2 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h2><h3 id="no-change" tabindex="-1">NO_CHANGE <a class="header-anchor" href="#no-change" aria-label="Permalink to &quot;NO_CHANGE&quot;">​</a></h3><p>Action indicating content is unchanged from previous refresh. Reuses existing asset ID from the registry without regenerating HTML or syncing to SFCC. Functionally equivalent to SKIP but semantically means &quot;same content continues.&quot; See <a href="/concepts/action-types.html">Action Types</a>.</p><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><h3 id="ocapi" tabindex="-1">OCAPI <a class="header-anchor" href="#ocapi" aria-label="Permalink to &quot;OCAPI&quot;">​</a></h3><p>Open Commerce API — Salesforce Commerce Cloud&#39;s REST API for managing content, campaigns, and slots programmatically. See <a href="/concepts/ocapi-readiness.html">OCAPI Readiness</a>.</p><h3 id="ocapi-payload" tabindex="-1">OCAPI Payload <a class="header-anchor" href="#ocapi-payload" aria-label="Permalink to &quot;OCAPI Payload&quot;">​</a></h3><p>JSON file (<code>ocapi-payload.json</code>) containing the complete campaign data formatted for SFCC API submission: campaign metadata, content assets (with HTML body), slot configurations, and slot bindings.</p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="pod" tabindex="-1">POD <a class="header-anchor" href="#pod" aria-label="Permalink to &quot;POD&quot;">​</a></h3><p>Production instance in SFCC. Content is replicated from staging to PODs.</p><h3 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h3><p>Composed view of multi-zone assets for visual verification before sync.</p><h3 id="producer-cli" tabindex="-1">Producer CLI <a class="header-anchor" href="#producer-cli" aria-label="Permalink to &quot;Producer CLI&quot;">​</a></h3><p>The set of 12 commands for web producers: <code>pull</code>, <code>select</code>, <code>build</code>, <code>edit</code>, <code>preview</code>, <code>push</code>, <code>replicate</code>, <code>done</code>, <code>commit</code>, <code>status</code>, <code>setup</code>, <code>help</code>. See <a href="/reference/commands.html#producer-commands">Commands</a>.</p><h3 id="pull" tabindex="-1">Pull <a class="header-anchor" href="#pull" aria-label="Permalink to &quot;Pull&quot;">​</a></h3><p><code>make pull</code> — the daily starting command. Combines git sync, data fetch, status dashboard, and date selection into one step. See <a href="/cli/pull.html">pull</a>.</p><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="refresh" tabindex="-1">Refresh <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;Refresh&quot;">​</a></h3><p>A data transfer object (DTO) containing wireframe data for a specific date. Holds all asset types, zones, and items parsed from the Excel/Smartsheet source. The input to the generation process. See <a href="/concepts/refresh-and-campaign.html">Refresh &amp; Campaign</a>.</p><h3 id="refresh-bundle" tabindex="-1">Refresh Bundle <a class="header-anchor" href="#refresh-bundle" aria-label="Permalink to &quot;Refresh Bundle&quot;">​</a></h3><p>A collection of all refreshes for a single date, stored as <code>refresh-bundle.json</code>. When a date has multiple refreshes (r1, r2, r3), they are bundled together.</p><h3 id="refresh-id" tabindex="-1">Refresh ID <a class="header-anchor" href="#refresh-id" aria-label="Permalink to &quot;Refresh ID&quot;">​</a></h3><p>Ordinal identifier for multiple refreshes on the same date: r1, r2, r3, etc. Assigned by start time order.</p><h3 id="registry" tabindex="-1">Registry <a class="header-anchor" href="#registry" aria-label="Permalink to &quot;Registry&quot;">​</a></h3><p>See <a href="#asset-registry">Asset Registry</a>.</p><h3 id="replication" tabindex="-1">Replication <a class="header-anchor" href="#replication" aria-label="Permalink to &quot;Replication&quot;">​</a></h3><p>Process of copying content from staging to production PODs. Currently requires manual trigger in Business Manager.</p><h3 id="remove" tabindex="-1">REMOVE <a class="header-anchor" href="#remove" aria-label="Permalink to &quot;REMOVE&quot;">​</a></h3><p>Action indicating content should be deleted from SFCC and unregistered.</p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="sfcc" tabindex="-1">SFCC <a class="header-anchor" href="#sfcc" aria-label="Permalink to &quot;SFCC&quot;">​</a></h3><p>Salesforce Commerce Cloud. The e-commerce platform this tool integrates with.</p><h3 id="site-id" tabindex="-1">Site ID <a class="header-anchor" href="#site-id" aria-label="Permalink to &quot;Site ID&quot;">​</a></h3><p>SFCC identifier for the website. Set via <code>SFCC_SITE_ID</code> environment variable.</p><h3 id="skip" tabindex="-1">SKIP <a class="header-anchor" href="#skip" aria-label="Permalink to &quot;SKIP&quot;">​</a></h3><p>Action indicating a zone should be completely ignored during processing. No HTML is generated, no sync occurs, and the registry is untouched. Different from NO_CHANGE: SKIP means &quot;don&#39;t process at all,&quot; while NO_CHANGE means &quot;content stays the same.&quot;</p><h3 id="slot" tabindex="-1">Slot <a class="header-anchor" href="#slot" aria-label="Permalink to &quot;Slot&quot;">​</a></h3><p>A designated area on an SFCC page where content can be displayed. Slots are filled by slot configurations.</p><h3 id="slotconfiguration" tabindex="-1">SlotConfiguration <a class="header-anchor" href="#slotconfiguration" aria-label="Permalink to &quot;SlotConfiguration&quot;">​</a></h3><p>Domain entity linking a ContentAsset to a specific slot within a Campaign. Defines when, where, and what content appears.</p><h3 id="slot-id" tabindex="-1">Slot ID <a class="header-anchor" href="#slot-id" aria-label="Permalink to &quot;Slot ID&quot;">​</a></h3><p>Unique identifier for a slot in SFCC. Examples: <code>global-promotion-banner</code>, <code>hp-top-banner</code>.</p><h3 id="smartsheet" tabindex="-1">Smartsheet <a class="header-anchor" href="#smartsheet" aria-label="Permalink to &quot;Smartsheet&quot;">​</a></h3><p>Cloud-based spreadsheet application used as a wireframe data source.</p><h3 id="staging" tabindex="-1">Staging <a class="header-anchor" href="#staging" aria-label="Permalink to &quot;Staging&quot;">​</a></h3><p>SFCC environment for testing content before production. Content syncs here first.</p><h3 id="sticky-date" tabindex="-1">Sticky Date <a class="header-anchor" href="#sticky-date" aria-label="Permalink to &quot;Sticky Date&quot;">​</a></h3><p>The currently selected working date, stored in <code>dev-env/{brand}/.current-date</code> (gitignored). Set by <code>make select</code> or <code>make pull</code>. Automatically used by <code>make build</code>, <code>make push</code>, <code>make done</code>, etc. so producers don&#39;t need to type <code>DATE=</code> on every command. See <a href="/cli/select.html">select</a>.</p><h3 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h3><p>Process of pushing campaign data to SFCC via OCAPI. Now accessed via <code>make push</code>, which adds automatic data quality validation. See <a href="/cli/push.html">push</a>.</p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h3><p>Handlebars file used to generate HTML content. Located in <code>templates/</code> directory.</p><h3 id="template-mode" tabindex="-1">Template Mode <a class="header-anchor" href="#template-mode" aria-label="Permalink to &quot;Template Mode&quot;">​</a></h3><p>Asset type mode where HTML is rendered from Handlebars templates using zone data.</p><h2 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U&quot;">​</a></h2><h3 id="update" tabindex="-1">UPDATE <a class="header-anchor" href="#update" aria-label="Permalink to &quot;UPDATE&quot;">​</a></h3><p>Action indicating modification to existing content. Reuses existing asset ID from registry.</p><h3 id="upload" tabindex="-1">Upload <a class="header-anchor" href="#upload" aria-label="Permalink to &quot;Upload&quot;">​</a></h3><p>Process of pushing only content assets (not campaign/slots) to SFCC. See <a href="/cli/upload.html">CLI: upload</a>.</p><h3 id="use-case" tabindex="-1">Use Case <a class="header-anchor" href="#use-case" aria-label="Permalink to &quot;Use Case&quot;">​</a></h3><p>Application layer class that orchestrates domain operations. Examples: GenerateDevFiles, SyncToSfcc, ParseExcel.</p><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><p>Process of checking templates and refresh data for SFCC compatibility. Runs automatically as part of <code>make push</code>. See <a href="/concepts/validation-rules.html">Validation Rules</a>.</p><h3 id="vitepress" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress" aria-label="Permalink to &quot;VitePress&quot;">​</a></h3><p>Static site generator used for this documentation.</p><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="wireframe" tabindex="-1">Wireframe <a class="header-anchor" href="#wireframe" aria-label="Permalink to &quot;Wireframe&quot;">​</a></h3><p>Excel or Smartsheet document containing campaign content data — the source input for the automation. Wireframes specify what promotional content goes live on which dates, including copy, links, actions (LAUNCH/UPDATE/REMOVE), and zone assignments. Also referred to as &quot;the Excel file&quot; or &quot;the spreadsheet.&quot;</p><h2 id="z" tabindex="-1">Z <a class="header-anchor" href="#z" aria-label="Permalink to &quot;Z&quot;">​</a></h2><h3 id="zone" tabindex="-1">Zone <a class="header-anchor" href="#zone" aria-label="Permalink to &quot;Zone&quot;">​</a></h3><p>A specific content area within an asset type. Multi-zone asset types (like Homepage) have many zones. See <a href="/concepts/slots-assets-zones.html">Slots, Assets, Zones</a>.</p><h3 id="zone-key" tabindex="-1">Zone Key <a class="header-anchor" href="#zone-key" aria-label="Permalink to &quot;Zone Key&quot;">​</a></h3><p>Identifier for a zone within an asset type. Examples: <code>HP_TOP_BANNER</code>, <code>HP_HERO</code>, <code>MAIN</code>.</p>',148)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
